export function sharePart(due: string, share: string): string {
  return formatCents(roundPct(hundredths(due) * hundredths(share), false));
}

/** A holder's part of a live claim: its amount times their share divided by 100, times the rate of the holder's own
 *  grade in force on the claim's date (`pct`) divided by 100, rounded like the claim (half up when `halfUp`, else half
 *  to even); 0.00 when their grade has no rate. Exact: worked in whole hundredths. */
export function holderPart(amount: string, share: string, pct: string | undefined, halfUp: boolean): string {
  if (pct === undefined) return '0.00';
  // amount (1/100) x share (1/100) x pct (1/100) / 10_000 is in 1/100_000_000 of a cent's worth; to cents is / 100_000_000.
  return formatCents(roundBy(hundredths(amount) * hundredths(share) * hundredths(pct), 100_000_000n, halfUp));
}

/** The rate of a holder's own grade in force on a live claim's date (undefined: none; see `holderPart`). */
export type HolderPct = (c: Claim, s: ClaimShare) => string | undefined;

/** A part of a claim a person holds of another's claim (see `Claim.shares`), or, `given`, the part (negative) a
 *  holder takes of the person's own claim. */
export type HeldPart = { claim: Claim; part: string; given?: boolean };

/** The parts a person (`personId`) holds of the claims among `claims` (the live ones) that count, and (`given`,
 *  negative) the parts others hold of theirs: a SETTLED claim's frozen with its due (`dueOfClaim`, n/a ones skipped),
 *  a live one's by the holder's own grade's rate (`holderPct`; one whose grade has none holds nothing). A claim
 *  whose due is n/a gives nothing away from its own person. */
export function heldParts(personId: number, claims: Claim[], dueOfClaim: (c: Claim) => string | null,
  holderPct: HolderPct, late: Late): HeldPart[] {
  const partOf = (c: Claim, s: ClaimShare): string | null => {
    if (c.settledDue !== null) return sharePart(c.settledDue, s.share);
    const pct = holderPct(c, s);
    return pct === undefined ? null : holderPart(c.amount, s.share, pct, roundsHalfUp(c, late));
  };
  const held: HeldPart[] = [];
  for (const c of claims) {
    if (!counts(c)) continue;
    if (c.personId === personId) {
      if ((c.shares ?? []).length === 0 || dueOfClaim(c) === null) continue;
      for (const s of c.shares ?? []) {
        const part = partOf(c, s);
        if (part !== null) held.push({ claim: c, part: formatCents(-hundredths(part)), given: true });
      }
      continue;
    }
    const share = (c.shares ?? []).find((s) => s.personId === personId);
    const part = share === undefined ? null : partOf(c, share);
    if (part !== null) held.push({ claim: c, part });
  }
  return held;
}

